class Solution {
public:
 TreeNode* replaceValueInTree(TreeNode* root){
  if(!root)return root;
  vector<TreeNode*> level(1,root);root->val=0;
  while(!level.empty()){
   vector<TreeNode*> next;long long sum=0;
   for(TreeNode* p:level){if(p->left){sum+=p->left->val;next.push_back(p->left);}if(p->right){sum+=p->right->val;next.push_back(p->right);}}
   for(TreeNode* p:level){int sib=(p->left?p->left->val:0)+(p->right?p->right->val:0);
    if(p->left)p->left->val=(int)(sum-sib);
    if(p->right)p->right->val=(int)(sum-sib);
   }
   level.swap(next);
  }return root;
 }
};
